/** Vrbo is a wordmark brand — set it as type rather than invent a symbol. */
export const VrboMark: React.FC<{ color: string; fontFamily: string }> = ({
  color,
  fontFamily,
}) => (
  <span
    style={{
      display: "flex",
      alignItems: "center",
      height: MARK_SIZE,
      fontFamily,
      fontSize: 34,
      fontWeight: 700,
      letterSpacing: -0.5,
      color,
      textTransform: "lowercase",
    }}
  >
    vrbo
  </span>
);

/** Not a brand: a booking that comes straight to the owner's own site. */
